9	func TestPickerStartsAtAskModule(t *testing.T) {
10		p := NewPicker(nil)
11		if p.State() != StateAskModule {
12			t.Errorf("initial state = %v, want StateAskModule", p.State())
13		}
14	}
15	
16	func TestPickerAdvancesOnEnter(t *testing.T) {
17		p := NewPicker(nil)
18		for _, r := range "iac/comply/aws" {
19			_, _ = p.Update(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{r}})
20		}
21		_, cmd := p.Update(tea.KeyMsg{Type: tea.KeyEnter})
22		// nil deps means no network cmd is dispatched, but state has advanced
23		// past validation. (See test in next assertion.)
24		_ = cmd
25		if p.HasError() {
26			t.Errorf("did not expect error for valid module; got: %v", p)
27		}
28	}
29	
30	func TestPickerRejectsBadAddressInline(t *testing.T) {
31		p := NewPicker(nil)
32		for _, r := range "garbage" {
33			_, _ = p.Update(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{r}})
34		}
35		_, cmd := p.Update(tea.KeyMsg{Type: tea.KeyEnter})
36		if cmd != nil {
37			t.Error("did not expect a tea.Cmd for invalid address")
38		}
39		if !p.HasError() {
40			t.Error("expected inline error on invalid address")
41		}
42	}
